// 查询函数
// ============================================================
/**
 * 将 JS Date 的 getDay() (0=周日) 转为中文星期
 */
export function weekdayToChinese(day) {
    return ["周日", "周一", "周二", "周三", "周四", "周五", "周六"][day] || "";
}
/**
 * 检查当前是否在学期内
 * - 上学期：9月 - 次年1月
 * - 下学期：2月 - 6月
 * - 假期：7月 - 8月
 */
export function isDuringSemester(date) {
    const month = date.getMonth() + 1; // 1-12
    return (month >= 9 || month <= 1) || (month >= 2 && month <= 6);
}
/**
 * 获取当前学期类型
 */
export function getSemesterType(date) {
    const month = date.getMonth() + 1;
    if (month >= 9 || month <= 1)
        return "上学期";
    if (month >= 2 && month <= 6)
        return "下学期";
    return "假期";
}
/**
 * 获取某个角色在指定时间的位置
 *
 * @param character 角色名
 * @param date 游戏时间
 * @param overrides 正文中解析出的角色位置覆盖（优先于日程表）
 * @returns 位置信息，如果角色没有日程则返回 null
 */
export function getCharacterLocation(character, date, overrides) {
    // ── 正文位置覆盖优先 ──
    // 如果正文中该角色出现在某地，直接使用该位置
    if (overrides && overrides[character]) {
        const overrideLoc = overrides[character];
        // overrides 值格式为 "parent/spot" 或 "parent"，拆分以保留父层级信息
        const slashIdx = overrideLoc.indexOf('/');
        if (slashIdx !== -1) {
            const parent = overrideLoc.substring(0, slashIdx);
            const spot = overrideLoc.substring(slashIdx + 1);
            return {
                character,
                location: spot,
                parentLocation: parent,
                activity: '剧情中',
                isFree: false,
            };
        }
        return {
            character,
            location: overrideLoc,
            activity: '剧情中',
            isFree: false,
        };
    }
    const schedule = CHARACTER_SCHEDULES[character];
    if (!schedule)
        return null;
    // 非学期内，所有角色空闲（yearRound 角色不受此限制）
    if (!isDuringSemester(date) && !schedule.yearRound) {
        return {
            character,
            location: schedule.defaultLocation || "",
            parentLocation: schedule.defaultParentLocation,
            activity: "空闲",
            isFree: true,
        };
    }
    const weekday = date.getDay(); // 0=周日
    const nowMin = date.getHours() * 60 + date.getMinutes();
    // 查找匹配的日程条目
    for (const entry of schedule.entries) {
        if (!entry.weekdays.includes(weekday))
            continue;
        if (entry.isFree)
            continue; // 跳过空闲条目
        if (entry.overnight) {
            // 跨天时段：如 23:00→02:00
            // 当前时间 >= startMin 或 < endMin
            if (nowMin >= entry.startMin || nowMin < entry.endMin) {
                return {
                    character,
                    location: entry.location,
                    parentLocation: entry.parentLocation,
                    activity: entry.activity,
                    isFree: false,
                };
            }
        }
        else {
            // 普通时段
            if (nowMin >= entry.startMin && nowMin < entry.endMin) {
                return {
                    character,
                    location: entry.location,
                    parentLocation: entry.parentLocation,
                    activity: entry.activity,
                    isFree: false,
                };
            }
        }
    }
    // 没有匹配的日程 → 空闲
    return {
        character,
        location: schedule.defaultLocation || "",
        parentLocation: schedule.defaultParentLocation,
        activity: "空闲",
        isFree: true,
    };
}
/**
 * 获取所有角色在指定时间的位置
 *
 * @param date 游戏时间
 * @param overrides 正文中解析出的角色位置覆盖（优先于日程表）
 * @returns 角色位置列表（不包含空闲/随机的角色，除非有 defaultLocation）
 */
export function getAllCharacterLocations(date, overrides) {
    const results = [];
    for (const character of Object.keys(CHARACTER_SCHEDULES)) {
        const loc = getCharacterLocation(character, date, overrides);
        if (loc && !loc.isFree) {
            results.push(loc);
        }
        else if (loc && loc.isFree && loc.location) {
            // 有默认位置的空闲角色也加入
            results.push(loc);
        }
    }
    return results;
}
/**
 * 获取在指定地点的所有角色
 *
 * @param spotName 地点名（匹配 LOCATION_INTERIORS / AREA_SPOTS 中的 name）
 * @param date 游戏时间
 * @param overrides 正文中解析出的角色位置覆盖（优先于日程表）
 * @param parentLocation 父地点名，用于区分不同父地点下的同名子位置（如"主卧"）
 * @returns 在该地点的角色列表
 */
export function getCharactersAtSpot(spotName, date, overrides, parentLocation) {
    const all = getAllCharacterLocations(date, overrides);
    return all.filter(loc => {
        if (loc.location !== spotName)
            return false;
        // 如果角色有 parentLocation（来自正文 overrides）且传入了 parentLocation，需要精确匹配父层级
        if (loc.parentLocation && parentLocation) {
            return loc.parentLocation === parentLocation;
        }
        return true;
    });
}
